INSERT INTO pages (slug, title_en, title_ru, eyebrow_en, eyebrow_ru, show_head, show_cta, seo_title_en, crumbs_json) VALUES ('', 'Customise Technology | Incomparable Quality', '', '', '', 0, 1, '', '[{"en":"Home","ru":"Главная","href":null}]');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 0, 'hero', '{"eyebrow_en":"Custom Technology · Incomparable Quality","eyebrow_ru":"Технологии под заказ · Непревзойдённое качество","title_en":"Getting to the bottom, faster!","title_ru":"Быстрее добираемся до дна!","body_en":"Hazleton Pumps develops and manufactures heavy-duty pumps and pump systems, custom built and designed for our clients'' specific needs and requirements. Proudly made in South Africa and deployed worldwide.","body_ru":"Hazleton Pumps разрабатывает и производит тяжёлые насосы и насосные системы, создаваемые по индивидуальному проекту под конкретные задачи заказчика. С гордостью производится в Южной Африке и поставляется по всему миру.","image":"/assets/img/hippo-pump.png","buttons":[{"label_en":"Request a Quote","label_ru":"Запросить КП","href":"/contact/"},{"label_en":"Explore the Hippo Range","label_ru":"Линейка Hippo","href":"/hippo-range/"}]}');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 1, 'text', '{"alt":true,"tight":true,"center":true,"body_en":"<p>Hazleton Pumps can provide spare parts and services to all Hazleton Pumps products and systems. This includes pumps originally manufactured in North America and Canada.</p>","body_ru":"<p>Hazleton Pumps поставляет запасные части и выполняет сервисное обслуживание для всей продукции и систем Hazleton Pumps, включая насосы, изначально изготовленные в Северной Америке и Канаде.</p>"}');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 2, 'cards', '{"variant":"feature","columns":3,"eyebrow_en":"Why Hazleton","eyebrow_ru":"Почему Hazleton","title_en":"Our competitive advantage","title_ru":"Наши конкурентные преимущества","items":[{"num":"01","title_en":"Customised Technology","title_ru":"Технологии под заказ","body_en":"Hazleton Pump systems are custom built and designed with pumps from the Hippo Slurry Pump Range, for each of our clients'' specific needs.","body_ru":"Насосные системы Hazleton собираются и проектируются с использованием насосов линейки Hippo под конкретные требования каждого клиента."},{"num":"02","title_en":"Adaptive Materials","title_ru":"Адаптируемые материалы","body_en":"Materials can be adjusted according to the type of application, from standard alloys to flameproof stainless steel.","body_ru":"Материалы подбираются под тип применения — от стандартных сплавов до взрывозащищённой нержавеющей стали."},{"num":"03","title_en":"Variable Capabilities","title_ru":"Гибкие характеристики","body_en":"Motors can be selected depending on the voltage and pole speeds required for the application.","body_ru":"Электродвигатели подбираются в зависимости от требуемого напряжения и частоты вращения."}]}');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 3, 'cards', '{"variant":"product","columns":2,"alt":true,"eyebrow_en":"What we build","eyebrow_ru":"Что мы производим","title_en":"Pump Systems","title_ru":"Насосные системы","items":[{"image":"/assets/img/solids-separation-system.svg","title_en":"Cyclone Solid Separation Pump System","title_ru":"Циклонная система отделения твёрдых частиц","body_en":"Ideal for applications where fluids with solids need to be separated from the liquid. Different materials are used depending on whether the fluid contains hardened solids or abrasive liquids.","body_ru":"Идеально подходит для задач, где твёрдые частицы необходимо отделить от жидкости. Материалы подбираются в зависимости от того, содержит ли среда затвердевшие частицы или абразивные жидкости.","link_href":"/pump-systems/cyclone-solids-separation-submersible-pumping-system/","link_en":"Find out more","link_ru":"Подробнее"},{"image":"/assets/img/high-head-system.svg","title_en":"High Head Slurry Series Pumping System","title_ru":"Серия высоконапорных шламовых систем","body_en":"For very deep pumping applications, able to pump heads of 250m per stage, through multiple stages. The system can be configured to the application depth, going as deep as required.","body_ru":"Для задач с большой глубиной откачки: напор до 250 м на ступень, возможно несколько ступеней. Система конфигурируется под глубину объекта — настолько глубоко, насколько требуется.","link_href":"/pump-systems/high-head-slurry-series-pumping-system/","link_en":"Find out more","link_ru":"Подробнее"}]}');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 4, 'text', '{"eyebrow_en":"Flagship product","eyebrow_ru":"Флагманский продукт","title_en":"Hippo Range","title_ru":"Линейка Hippo","body_en":"<p class=''lede''><strong>Your ally in pumping corrosive and acidic slurries.</strong> The award-winning Hippo Slurry Pump Range is the workhorse for the continuous, harsh demands of mining and mineral processing. Custom built, it provides pumping solutions that are robust, rugged, reliable and flexible — from high-volume dewatering to settled-out acidic and corrosive slurries. The range can be built to explosion-proof standard IEC 60079-1:2005 and is available in various formats and applications.</p>","body_ru":"<p class=''lede''><strong>Ваш надёжный партнёр в перекачке коррозионных и кислотных шламов.</strong> Удостоенная наград линейка шламовых насосов Hippo — это рабочая лошадка для непрерывных и тяжёлых условий горнодобывающей и перерабатывающей промышленности. Насосы изготавливаются по индивидуальному проекту и обеспечивают надёжные, прочные и гибкие решения — от высокообъёмного водоотлива до осевших кислотных и коррозионных шламов. Линейка может изготавливаться во взрывозащищённом исполнении по стандарту IEC 60079-1:2005 и доступна в различных конфигурациях.</p>"}');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 5, 'cards', '{"variant":"product","columns":2,"items":[{"image":"/assets/img/hippo-pump-top-suction.png","title_en":"Submersibles","title_ru":"Погружные насосы","body_en":"All-metal heavy-duty submersible slurry pumps, capable of pumping abrasive and corrosive liquids with capacities up to 1500 l/s and heads up to 200 m.","body_ru":"Цельнометаллические погружные шламовые насосы повышенной прочности для перекачки абразивных и коррозионных жидкостей, производительность до 1500 л/с, напор до 200 м.","link_href":"/hippo-range/submersibles/","link_en":"Configurations","link_ru":"Конфигурации"},{"image":"/assets/img/hippo-vb-range.png","title_en":"Verticals","title_ru":"Вертикальные насосы","body_en":"The world''s most versatile vertical spindle pump range — Bottom Suction, Bottom Discharge, Top Suction and Vortex configurations, heads up to 110 m and flow up to 1500 l/s.","body_ru":"Самая универсальная в мире линейка вертикальных шпиндельных насосов — конфигурации с нижним всасыванием, нижним нагнетанием, верхним всасыванием и вихревая — напор до 110 м, расход до 1500 л/с.","link_href":"/hippo-range/verticals/","link_en":"Configurations","link_ru":"Конфигурации"}]}');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 6, 'textImage', '{"alt":true,"body_en":"<p class=''lede''>The Hippo Slurry Pump Range was designed and developed to meet the harsh, continuous conditions of the mining and mineral-processing industries of Southern Africa. Capable of running dry and operating across a wide range of temperatures, the Hippo Pump Range is the ideal solution from high-volume dewatering to harsh, abrasive applications — with a custom-built solution for every application. Our pumps and pump systems have proven equally effective in Canada, South America, Australia, the Middle East and Russia.</p>","body_ru":"<p class=''lede''>Линейка шламовых насосов Hippo была разработана для суровых и непрерывных условий горнодобывающей и перерабатывающей промышленности Южной Африки. Способные работать «на сухом ходу» и в широком диапазоне температур, насосы Hippo — идеальное решение как для высокообъёмного водоотлива, так и для тяжёлых абразивных задач, с индивидуальным решением под каждое применение. Наши насосы и насосные системы доказали свою эффективность и за пределами региона — в Канаде, Южной Америке, Австралии, на Ближнем Востоке и в России.</p>","image":"/assets/img/world-map.svg","image_side":"right"}');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 7, 'cards', '{"variant":"plain","columns":3,"eyebrow_en":"Industries","eyebrow_ru":"Отрасли","title_en":"Our experience by industry","title_ru":"Наш опыт по отраслям","items":[{"title_en":"MINING","title_ru":"Горнодобывающая отрасль","body_en":"All sectors of mining and mineral extraction: coal, platinum, gold, iron and ore.","body_ru":"Все сегменты горной добычи и переработки полезных ископаемых: уголь, платина, золото, железо и руда."},{"title_en":"Pulp, Paper & Sugar","title_ru":"Целлюлоза, бумага и сахар","body_en":"Aggressive and abrasive solids.","body_ru":"Агрессивные и абразивные твёрдые частицы."},{"title_en":"Chemical & Processing","title_ru":"Химия и переработка","body_en":"Including oil sands, bitumen, petrochemical, fertiliser and explosive industries.","body_ru":"Включая нефтяные пески, битум, нефтехимию, удобрения и взрывоопасные производства."},{"title_en":"Nuclear","title_ru":"Атомная промышленность","body_en":"Specifically designed for high temperatures and contamination.","body_ru":"Специальные решения для высоких температур и загрязнённых сред."},{"title_en":"Foundries & Steel Production","title_ru":"Литейное и сталелитейное производство","body_en":"Cooling, water returns and concentrated abrasive solids.","body_ru":"Охлаждение, оборотная вода и концентрированные абразивные твёрдые частицы."},{"title_en":"Power Generation, Municipal Services & Waste Management","title_ru":"Энергетика, ЖКХ и утилизация отходов","body_en":"Ash, water treatment and waste disposal.","body_ru":"Зола, водоочистка и утилизация отходов."},{"title_en":"Sand, Gravel, Ceramic & General Construction","title_ru":"Песок, гравий, керамика и строительство","body_en":"Where high concentrations of abrasive solids are present.","body_ru":"Там, где присутствуют высокие концентрации абразивных частиц."}]}');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 8, 'logos', '{"title_en":"Proudly associated","title_ru":"Партнёрские ассоциации","items":[{"image":"/assets/img/assoc-sassda.webp","alt_en":"SASSDA"},{"image":"/assets/img/assoc-flameproof.webp","alt_en":"South African Flameproof Association"},{"image":"/assets/img/assoc-foundrymen.webp","alt_en":"South African Institute of Foundrymen"},{"image":"/assets/img/assoc-sapsda.webp","alt_en":"SAPSDA"},{"image":"/assets/img/assoc-sa-capital-equipment.webp","alt_en":"SA Capital Equipment"}]}');
INSERT INTO pages (slug, title_en, title_ru, eyebrow_en, eyebrow_ru, show_head, show_cta, seo_title_en, crumbs_json) VALUES ('history', 'History', 'История', 'About Us', 'О компании', 1, 1, '', '[{"en":"Home","ru":"Главная","href":"/"},{"en":"History","ru":"История","href":null}]');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 0, 'textImage', '{"title_en":"A family-owned and managed pump manufacturer","title_ru":"Семейный производитель насосов","image":"/assets/img/mining-site.webp","body_en":"<p>Founded in 1979, Hazleton Pumps is a family-owned business located in Centurion, Gauteng, South Africa. It began by repairing submersible pumps and electric motors for mines and industry. The harsh mining conditions in South Africa caused a high failure rate in these repaired pumps, which led to the design, development and manufacture of specialised pumping solutions capable of pumping acidic liquids containing solids under a wide range of conditions.</p>\\n      <p>The main cause of submersible pump failure is the pump running dry and overheating. This was overcome by filling the motor housing with oil, which serves two functions: dissipating heat from the electrical winding, and lubricating the bearings and mechanical seals.</p>\\n      <p>The motor housing containing the rotor and stator is separated from the discharge pressure of the pumped liquid using a cantilever shaft design with a double-discharge volute — and by applying the latest design software, the Hippo Submersible Slurry Pump Range was born.</p>\\n      <p>Manufactured as standard from specialised materials such as 28% hard-chrome castings for abrasive applications and Duplex Stainless Steel alloys (CD4MCu) castings for acidic environments, and with quality as a core objective, all Hippo Submersible Slurry Pumps are manufactured to comply with ISO 9001:2015 and IEC 60079-1.</p>\\n      <p>A customer-centric approach is followed, building long-term, committed, sustainable relationships as specific, specialised pumps are designed, developed and manufactured in collaboration with customers to meet their individual requirements — with products that are reliable, low-maintenance, sustainable, efficient and offer a reasonable cost of ownership.</p>","body_ru":"<p>Компания Hazleton Pumps основана в 1979 году как семейное предприятие в городе Сентурион, провинция Гаутенг, ЮАР. Изначально компания занималась ремонтом погружных насосов и электродвигателей для горнодобывающих предприятий. Из-за тяжёлых условий эксплуатации в южноафриканских шахтах отремонтированные насосы часто выходили из строя, что привело к разработке, проектированию и производству специализированных насосных решений, способных перекачивать кислотные жидкости с содержанием твёрдых частиц в самых разных условиях.</p>\\n      <p>Главная причина отказа погружных насосов — работа «на сухом ходу» и перегрев. Эта проблема была решена заполнением корпуса электродвигателя маслом, которое выполняет две функции: отводит тепло от электрической обмотки и смазывает подшипники и торцевые уплотнения.</p>\\n      <p>Корпус двигателя с ротором и статором отделён от давления нагнетания перекачиваемой жидкости за счёт консольной конструкции вала с двухспиральным корпусом (double-discharge volute) — а с применением новейшего программного обеспечения для проектирования появилась на свет линейка погружных шламовых насосов Hippo.</p>\\n      <p>Как правило, насосы изготавливаются из специальных материалов — например, из хромистого чугуна (28% хрома) для абразивных сред и дуплексной нержавеющей стали (CD4MCu) для кислотных сред. Качество — ключевой приоритет компании: все погружные шламовые насосы Hippo производятся в соответствии со стандартами ISO 9001:2015 и IEC 60079-1.</p>\\n      <p>Компания придерживается клиентоориентированного подхода, выстраивая долгосрочные и устойчивые отношения с заказчиками: специализированные насосы разрабатываются и производятся в сотрудничестве с клиентом, под его индивидуальные требования — надёжные, простые в обслуживании, экономичные и эффективные в эксплуатации.</p>","image_side":"left"}');
