INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 0, 'cards', '{"variant":"product","columns":2,"items":[{"image":"/assets/img/solids-separation-system.svg","title_en":"Cyclone Solid Separation Pump System","title_ru":"Циклонная система отделения твёрдых частиц","body_en":"Ideal for applications where fluids with solids need to be separated from the liquid. Different materials are used depending on whether the fluid contains hardened solids or abrasive liquids.","body_ru":"Идеально подходит для задач, где твёрдые частицы необходимо отделить от жидкости. Материалы подбираются в зависимости от того, содержит ли среда затвердевшие частицы или абразивные жидкости.","link_href":"/pump-systems/cyclone-solids-separation-submersible-pumping-system/","link_en":"Find out more","link_ru":"Подробнее"},{"image":"/assets/img/high-head-system.svg","title_en":"High Head Slurry Series Pumping System","title_ru":"Серия высоконапорных шламовых систем","body_en":"For very deep pumping applications, able to pump heads of 250 m per stage through multiple stages. The system is configured to the application depth, going as deep as required.","body_ru":"Для задач с большой глубиной откачки: напор до 250 м на ступень, возможно несколько ступеней. Система конфигурируется под глубину объекта — настолько глубоко, насколько требуется.","link_href":"/pump-systems/high-head-slurry-series-pumping-system/","link_en":"Find out more","link_ru":"Подробнее"}]}');
INSERT INTO pages (slug, title_en, title_ru, eyebrow_en, eyebrow_ru, show_head, show_cta, seo_title_en, crumbs_json) VALUES ('pump-systems/cyclone-solids-separation-submersible-pumping-system', 'Cyclone Solid Separation Pump System', 'Циклонная система отделения твёрдых частиц', 'Pump Systems', 'Насосные системы', 1, 1, '', '[{"en":"Home","ru":"Главная","href":"/"},{"en":"Pump Systems","ru":"Насосные системы","href":"/pump-systems/"},{"en":"Cyclone Solids Separation","ru":"Циклонное отделение","href":null}]');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 0, 'text', '{"body_en":"<p class=''lede''>The Cyclone Solid Separation Pump System is ideal for applications where solids need to be separated from a fluid. Different materials are used depending on whether the pumped fluid contains hardened solids or abrasive liquids.</p>","body_ru":"<p class=''lede''>Циклонная система отделения твёрдых частиц идеально подходит для задач, в которых твёрдые частицы необходимо отделить от жидкости. Материалы подбираются в зависимости от того, содержит ли перекачиваемая среда затвердевшие частицы или абразивные жидкости.</p>","max_width":"980px"}');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 1, 'panelGrid', '{"items":[{"title_en":"Objective","title_ru":"Задача","body_en":"To separate the solids contained in the fluid from the liquid.","body_ru":"Отделить твёрдые частицы, содержащиеся в жидкости, от самой жидкости."},{"title_en":"Operation","title_ru":"Принцип работы","body_en":"The fluid containing solids is pumped using a Hippo Submersible Pump through a cyclone, where the solids are separated from the liquid.","body_ru":"Жидкость с твёрдыми частицами перекачивается погружным насосом Hippo через циклон, в котором происходит отделение твёрдых частиц от жидкости."},{"title_en":"Application","title_ru":"Применение","body_en":"Suitable for any application where solids must be removed from a liquid.","body_ru":"Подходит для любых задач, где твёрдые частицы необходимо удалить из жидкости."},{"title_en":"Duty","title_ru":"Рабочие параметры","body_en":"The head and volume to be pumped determine the submersible pump size, as well as the flow rate through the cyclone.","body_ru":"Напор и объём перекачки определяют типоразмер погружного насоса, а также пропускную способность циклона."},{"title_en":"Materials of construction","title_ru":"Материалы изготовления","body_en":"High-chrome castings are used so the system can pump liquids containing hardened solids; for corrosive liquids, duplex stainless steel is the standard casting material.","body_ru":"Для перекачки жидкостей с затвердевшими частицами применяется хромистый чугун; для коррозионных жидкостей стандартным материалом является дуплексная нержавеющая сталь.","wide":true}]}');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 2, 'image', '{"image":"/assets/img/solids-separation-diagram.png"}');
INSERT INTO pages (slug, title_en, title_ru, eyebrow_en, eyebrow_ru, show_head, show_cta, seo_title_en, crumbs_json) VALUES ('pump-systems/high-head-slurry-series-pumping-system', 'High Head Slurry Series Pumping System', 'Серия высоконапорных шламовых систем', 'Pump Systems', 'Насосные системы', 1, 1, '', '[{"en":"Home","ru":"Главная","href":"/"},{"en":"Pump Systems","ru":"Насосные системы","href":"/pump-systems/"},{"en":"High Head Slurry Series","ru":"Высоконапорная серия","href":null}]');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 0, 'text', '{"body_en":"<p class=''lede''>For very deep pumping applications, the High Head Slurry Series Pumping System is a viable solution able to pump heads of 250 m per stage, through multiple stages. The system is configured to the application depth, going as deep as required.</p>","body_ru":"<p class=''lede''>Для задач с большой глубиной откачки серия высоконапорных шламовых систем обеспечивает напор до 250 м на ступень, с возможностью установки нескольких ступеней. Система конфигурируется под глубину объекта — настолько глубоко, насколько требуется.</p>","max_width":"980px"}');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 1, 'panelGrid', '{"items":[{"title_en":"Objective","title_ru":"Задача","body_en":"To create an effectively unlimited pumping head, enabling heads of up to 250 m per stage.","body_ru":"Обеспечить практически неограниченный напор — до 250 м на ступень."},{"title_en":"Operation","title_ru":"Принцип работы","body_en":"An unlimited head is achieved by using the Hippo High Head Slurry Submersible Pump and feeding the discharge of the first pump into the inlet of the second, and so on. With continuous “run-dry” capability, the risk of overheating when running dry is eliminated.","body_ru":"Неограниченный напор достигается за счёт использования высоконапорного погружного насоса Hippo: выход первого насоса подаётся на вход второго, и так далее. Благодаря способности непрерывной работы «на сухом ходу» риск перегрева при работе без жидкости исключён."},{"title_en":"Application","title_ru":"Применение","body_en":"Built to explosion-proof standard.","body_ru":"Исполнение по взрывозащищённому стандарту."},{"title_en":"Duty","title_ru":"Рабочие параметры","body_en":"Heads of up to 250 m per stage can be achieved.","body_ru":"Достижимый напор — до 250 м на ступень."},{"title_en":"Materials of construction","title_ru":"Материалы изготовления","body_en":"Duplex Stainless Steel such as CD4MCu is used, giving the capability to pump acidic liquids containing solids.","body_ru":"Применяется дуплексная нержавеющая сталь, например CD4MCu, что позволяет перекачивать кислотные жидкости с содержанием твёрдых частиц.","wide":true}]}');
INSERT INTO pages (slug, title_en, title_ru, eyebrow_en, eyebrow_ru, show_head, show_cta, seo_title_en, crumbs_json) VALUES ('hippo-range', 'Hippo Range', 'Линейка Hippo', 'Flagship product', 'Флагманский продукт', 1, 1, '', '[{"en":"Home","ru":"Главная","href":"/"},{"en":"Hippo Range","ru":"Линейка Hippo","href":null}]');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 0, 'text', '{"body_en":"<p class=''lede''><strong>Your ally in pumping corrosive and acidic slurries.</strong> The award-winning Hippo Slurry Pump Range is the perfect workhorse for the continuous, harsh demands of mining and mineral processing. Custom built, it delivers pumping solutions that are robust, rugged, reliable and flexible. Capacities are extremely diverse, assisting applications from high-volume dewatering to settled-out acidic and corrosive slurries. The range can be built to explosion-proof standard IEC 60079-1:2005 and is available in various formats and applications.</p>","body_ru":"<p class=''lede''><strong>Ваш надёжный партнёр в перекачке коррозионных и кислотных шламов.</strong> Удостоенная наград линейка шламовых насосов Hippo — рабочая лошадка для непрерывных и тяжёлых условий горнодобывающей и перерабатывающей промышленности. Насосы изготавливаются по индивидуальному проекту и обеспечивают надёжные, прочные и гибкие решения. Диапазон производительности чрезвычайно широк — от высокообъёмного водоотлива до осевших кислотных и коррозионных шламов. Линейка может изготавливаться во взрывозащищённом исполнении по стандарту IEC 60079-1:2005 и доступна в различных конфигурациях.</p>","max_width":"980px"}');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 1, 'cards', '{"variant":"product","columns":2,"alt":true,"items":[{"image":"/assets/img/hippo-pump-top-suction.png","title_en":"Hippo Heavy Duty Slurry Submersible Pumps","title_ru":"Погружные шламовые насосы Hippo повышенной прочности","body_en":"Designed and developed to pump corrosive and abrasive slurries — named after the hippopotamus, a robust and strong inhabitant of Africa''s waterways. The range includes both an all-metal heavy-duty submersible and a vertical-spindle cantilever pump range.","body_ru":"Разработаны для перекачки коррозионных и абразивных шламов — название линейки отсылает к бегемоту, крепкому и сильному обитателю африканских водоёмов. Линейка включает как цельнометаллические погружные насосы повышенной прочности, так и вертикальные шпиндельные консольные насосы.","link_href":"/hippo-range/submersibles/","link_en":"Configurations","link_ru":"Конфигурации"},{"image":"/assets/img/hippo-vb-range.png","title_en":"Hippo Cantilever Vertical Spindle Heavy Duty Slurry & De-watering Pumps","title_ru":"Консольные вертикальные шпиндельные насосы Hippo для шлама и водоотлива","body_en":"The world''s most versatile vertical-spindle pump range: an all-metal design with Bottom Suction, Bottom Discharge, Top Suction and Vortex configurations. Proven reliability lets it handle high-density abrasive and corrosive slurries, running dry at heads up to 110 m and flows up to 1500 l/s.","body_ru":"Самая универсальная в мире линейка вертикальных шпиндельных насосов: цельнометаллическая конструкция в конфигурациях с нижним всасыванием, нижним нагнетанием, верхним всасыванием и вихревая. Проверенная надёжность позволяет работать с плотными абразивными и коррозионными шламами, выдерживая работу «на сухом ходу» при напоре до 110 м и расходе до 1500 л/с.","link_href":"/hippo-range/verticals/","link_en":"Configurations","link_ru":"Конфигурации"}]}');
INSERT INTO pages (slug, title_en, title_ru, eyebrow_en, eyebrow_ru, show_head, show_cta, seo_title_en, crumbs_json) VALUES ('hippo-range/submersibles', 'Submersibles', 'Погружные насосы', 'Hippo Range', 'Линейка Hippo', 1, 1, '', '[{"en":"Home","ru":"Главная","href":"/"},{"en":"Hippo Range","ru":"Линейка Hippo","href":"/hippo-range/"},{"en":"Submersibles","ru":"Погружные насосы","href":null}]');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 0, 'text', '{"body_en":"<p class=''lede''><strong>Hippo Heavy Duty Slurry Submersible Pumps.</strong> Designed and developed to pump corrosive and abrasive slurries. The range consists of both an all-metal heavy-duty submersible and a vertical-spindle cantilever pump range.</p>","body_ru":"<p class=''lede''><strong>Погружные шламовые насосы Hippo повышенной прочности.</strong> Разработаны для перекачки коррозионных и абразивных шламов. Линейка включает как цельнометаллические погружные насосы повышенной прочности, так и вертикальные шпиндельные консольные насосы.</p>","max_width":"980px"}');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 1, 'cards', '{"variant":"product","columns":2,"alt":true,"items":[{"image":"/assets/img/sb-design-features.jpg","title_en":"Submersible Bottom Suction (SB)","title_ru":"Погружной насос с нижним всасыванием (SB)","body_en":"Used where solid particles have already settled out and need to be agitated before being pumped. All-metal construction with high-chrome hydraulics as standard; available in duplex stainless steel for acidic environments.","body_ru":"Применяется там, где твёрдые частицы уже осели и требуют взмучивания перед откачкой. Цельнометаллическая конструкция со стандартной гидравликой из хромистого чугуна; доступно исполнение из дуплексной нержавеющей стали для кислотных сред.","link_href":"/hippo-range/submersibles/submersible-bottom-suction/","link_en":"SB Series","link_ru":"Серия SB"},{"image":"/assets/img/st-design-features.jpg","title_en":"Submersible Top Suction (ST)","title_ru":"Погружной насос с верхним всасыванием (ST)","body_en":"Used where high discharge pressures exist and for pumping liquids with entrapped air (froth pumping) — pumping excess liquid away while solids remain in the sump for mechanical removal.","body_ru":"Применяется при высоком давлении нагнетания и при перекачке жидкостей с вовлечённым воздухом (пенные среды) — откачивает избыток жидкости, оставляя твёрдые частицы в приямке для механического удаления.","link_href":"/hippo-range/submersibles/submersible-top-suction/","link_en":"ST Series","link_ru":"Серия ST"}]}');
INSERT INTO pages (slug, title_en, title_ru, eyebrow_en, eyebrow_ru, show_head, show_cta, seo_title_en, crumbs_json) VALUES ('hippo-range/submersibles/submersible-bottom-suction', 'Submersible Bottom Suction Pump', 'Погружной насос с нижним всасыванием', 'Hippo Range', 'Линейка Hippo', 1, 1, '', '[{"en":"Home","ru":"Главная","href":"/"},{"en":"Hippo Range","ru":"Линейка Hippo","href":"/hippo-range/"},{"en":"Submersibles","ru":"Погружные насосы","href":"/hippo-range/submersibles/"},{"en":"Submersible Bottom Suction Pump","ru":"Погружной насос с нижним всасыванием","href":null}]');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 0, 'backLink', '{"href":"/hippo-range/submersibles/","label_en":"Submersibles","label_ru":"Погружные насосы"}');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 1, 'textImage', '{"image":"/assets/img/sb-design-features.jpg","body_en":"<p class=''lede''>The Hippo Submersible Bottom Suction Pump Range is used where solid particles have already settled out and need to be agitated before being pumped. The all-metal pump, with high-chrome hydraulics as standard, offers durability and high efficiency, and can be manufactured in duplex stainless steel alloys (e.g. CD4MCu) for acidic environments. A wide range of accessories is available to suit client requirements.</p>","body_ru":"<p class=''lede''>Погружной насос Hippo с нижним всасыванием применяется там, где твёрдые частицы в жидкости уже осели и требуют взмучивания перед откачкой. Цельнометаллическая конструкция со стандартной гидравликой из хромистого чугуна обеспечивает долговечность и высокую эффективность; доступно исполнение из дуплексной нержавеющей стали (например, CD4MCu) для кислотных сред. Насос может комплектоваться широким набором опций под требования заказчика.</p>"}');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 2, 'list', '{"items":[{"en":"Capable of pumping abrasive and corrosive liquids","ru":"Перекачка абразивных и коррозионных жидкостей"},{"en":"Capacities up to 1500 l/s and heads up to 150 m","ru":"Производительность до 1500 л/с, напор до 150 м"},{"en":"Flameproof certification to IEC 60079-1","ru":"Взрывозащищённое исполнение по IEC 60079-1"},{"en":"Power installed from 3 kW up to 1000 kW","ru":"Мощность от 3 кВт до 1000 кВт"},{"en":"Voltage supply up to 6.6 kV at both 50 & 60 Hz","ru":"Напряжение питания до 6,6 кВ при 50 и 60 Гц"},{"en":"Liquids up to 120 °C","ru":"Жидкости с температурой до 120 °C"},{"en":"Can run dry","ru":"Работа «на сухом ходу»"}]}');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 3, 'advantages', '{"title_en":"Advantages of the SB configuration","title_ru":"Преимущества конфигурации SB","items":[{"label_en":"Twin Volute Discharge Design","label_ru":"Двухспиральная конструкция нагнетания","body_en":"radial forces are balanced out in the volute, minimising bearing load and increasing bearing life while enabling more efficient pumping.","body_ru":"радиальные силы уравновешиваются в корпусе, что снижает нагрузку на подшипники, увеличивает их ресурс и повышает эффективность перекачки."},{"label_en":"Agitator","label_ru":"Мешалка (агитатор)","body_en":"the Hippo heavy-duty slurry pump range can be fitted with an agitator.","body_ru":"насосы Hippo повышенной прочности могут комплектоваться мешалкой."},{"label_en":"“Run Dry”","label_ru":"«Сухой ход»","body_en":"the stator housing is filled with oil, which dissipates heat away from the winding, enabling continuous dry running under full, partial or non-submerged conditions.","body_ru":"корпус статора заполнен маслом, которое отводит тепло от обмотки, обеспечивая непрерывную работу на сухом ходу при полном, частичном или отсутствующем погружении."},{"label_en":"Cantilever Shaft","label_ru":"Консольный вал","body_en":"the Twin Volute design uses a cantilever shaft, separating the wet end from the motor end without support bearings.","body_ru":"двухспиральная конструкция использует консольный вал, отделяющий проточную часть от двигателя без опорных подшипников."},{"label_en":"Mechanical Seals","label_ru":"Торцевые уплотнения","body_en":"dissociated from the wet end as a result of the cantilever shaft, subject only to submergence pressure — extending seal life.","body_ru":"благодаря консольному валу отделены от проточной части и работают только под давлением погружения, что увеличивает их срок службы."},{"label_en":"Moisture Detection","label_ru":"Контроль влажности","body_en":"a built-in moisture detector cuts power to the pump if the mechanical seals fail, preventing winding damage.","body_ru":"встроенный датчик влажности отключает питание насоса при отказе торцевых уплотнений, предотвращая повреждение обмотки."},{"label_en":"Hydraulic-End Designs","label_ru":"Исполнения гидравлической части","body_en":"a specific hydraulic end is available for every application — high head or high volume, large or irregular solids, abrasive or corrosive liquids.","body_ru":"под каждую задачу доступна своя гидравлическая часть — для высокого напора или большого объёма, крупных или неправильной формы частиц, абразивных или коррозионных сред."}]}');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 4, 'text', '{"title_en":"IEC (SANS) standards","title_ru":"Стандарты IEC (SANS)","body_en":"<p>To pump in explosive environments, all Hippo Submersible Pumps comply with IEC (SANS) 60079-0:2005 and IEC (SANS) 60079-1:2004.</p><p>Type SBO — Open Vane Type Impeller with Agitator. Type SBC — Closed Vane Type Impeller with Agitator Extension & Spray-Bar.</p>","body_ru":"<p>Для работы во взрывоопасных средах все погружные насосы Hippo соответствуют стандартам IEC (SANS) 60079-0:2005 и IEC (SANS) 60079-1:2004.</p><p>Тип SBO — открытое рабочее колесо с мешалкой. Тип SBC — закрытое рабочее колесо с удлинённой мешалкой и распылительной штангой.</p>"}');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 5, 'text', '{"title_en":"Applications","title_ru":"Применение","body_en":"<p>The Hippo SB range excels in complex slurry and de-watering applications. Its compact design and high-pressure capability suit pits, pontoons, or temporary and fixed installations.</p>","body_ru":"<p>Насосы серии Hippo SB отлично подходят для сложных задач перекачки шлама и водоотлива. Компактная конструкция и способность работать при высоком давлении позволяют использовать их в карьерах, на понтонах, а также во временных и стационарных установках.</p>"}');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 6, 'list', '{"style":"tag","items":[{"en":"Mineral process plants","ru":"Перерабатывающие предприятия"},{"en":"Mineral excavations","ru":"Горные выработки"},{"en":"Coal slurries","ru":"Угольные шламы"},{"en":"Oil sands","ru":"Нефтяные пески"},{"en":"Fly-ash sumps and ponds","ru":"Золоотвалы и пруды-накопители"},{"en":"Slurry transfer pumping","ru":"Перекачка шлама"},{"en":"Dredging","ru":"Дноуглубительные работы"},{"en":"Lime slurry removal","ru":"Удаление известкового шлама"},{"en":"Emergency dump pond","ru":"Аварийные пруды-накопители"},{"en":"Phosphoric acid plants","ru":"Производство фосфорной кислоты"},{"en":"Clay slurries","ru":"Глинистые шламы"}]}');
INSERT INTO pages (slug, title_en, title_ru, eyebrow_en, eyebrow_ru, show_head, show_cta, seo_title_en, crumbs_json) VALUES ('hippo-range/submersibles/submersible-top-suction', 'Submersible Top Suction Pump', 'Погружной насос с верхним всасыванием', 'Hippo Range', 'Линейка Hippo', 1, 1, '', '[{"en":"Home","ru":"Главная","href":"/"},{"en":"Hippo Range","ru":"Линейка Hippo","href":"/hippo-range/"},{"en":"Submersibles","ru":"Погружные насосы","href":"/hippo-range/submersibles/"},{"en":"Submersible Top Suction Pump","ru":"Погружной насос с верхним всасыванием","href":null}]');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 0, 'backLink', '{"href":"/hippo-range/submersibles/","label_en":"Submersibles","label_ru":"Погружные насосы"}');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 1, 'textImage', '{"image":"/assets/img/st-design-features.jpg","body_en":"<p class=''lede''>The Hippo Submersible Top Suction Slurry Pump Range is used where high discharge pressures exist and for pumping liquids with entrapped air (froth pumping). The all-metal pump, with high-chrome hydraulics as standard, offers durability and high efficiency, and can be manufactured in duplex stainless steel alloys (e.g. CD4MCu) for acidic environments. The Top Suction design pumps excess liquid away while the maximum amount of solids remains in the sump to be removed mechanically.</p>","body_ru":"<p class=''lede''>Погружной насос Hippo с верхним всасыванием применяется при высоком давлении нагнетания и для перекачки жидкостей с вовлечённым воздухом (пенные среды). Цельнометаллическая конструкция со стандартной гидравликой из хромистого чугуна обеспечивает долговечность и высокую эффективность; доступно исполнение из дуплексной нержавеющей стали (например, CD4MCu) для кислотных сред. Конструкция с верхним всасыванием откачивает избыток жидкости, оставляя максимум твёрдых частиц в приямке для последующего механического удаления.</p>"}');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 2, 'list', '{"items":[{"en":"Capable of pumping abrasive and corrosive liquids","ru":"Перекачка абразивных и коррозионных жидкостей"},{"en":"Capacities up to 1500 l/s and heads up to 200 m","ru":"Производительность до 1500 л/с, напор до 200 м"},{"en":"Flameproof to IEC 60079-1","ru":"Взрывозащищённое исполнение по IEC 60079-1"},{"en":"Power installed from 3 kW up to 1000 kW","ru":"Мощность от 3 кВт до 1000 кВт"},{"en":"Voltage supply up to 6.6 kV at both 50 & 60 Hz","ru":"Напряжение питания до 6,6 кВ при 50 и 60 Гц"},{"en":"Liquids up to 120 °C","ru":"Жидкости с температурой до 120 °C"},{"en":"Suitable for froth pumping","ru":"Подходит для пенных сред"},{"en":"Can run dry","ru":"Работа «на сухом ходу»"}]}');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 3, 'advantages', '{"title_en":"Advantages of the ST configuration","title_ru":"Преимущества конфигурации ST","items":[{"label_en":"Twin Volute Discharge Design","label_ru":"Двухспиральная конструкция нагнетания","body_en":"radial forces are balanced out in the volute, minimising bearing load and increasing bearing life while enabling more efficient pumping.","body_ru":"радиальные силы уравновешиваются в корпусе, что снижает нагрузку на подшипники, увеличивает их ресурс и повышает эффективность перекачки."},{"label_en":"Lifting Bracket","label_ru":"Подъёмная скоба","body_en":"allows the pump to be lowered while in operation.","body_ru":"позволяет опускать насос во время работы."},{"label_en":"“Run Dry”","label_ru":"«Сухой ход»","body_en":"the stator housing is filled with oil, which dissipates heat away from the winding, enabling continuous dry running under full, partial or non-submerged conditions.","body_ru":"корпус статора заполнен маслом, которое отводит тепло от обмотки, обеспечивая непрерывную работу на сухом ходу при полном, частичном или отсутствующем погружении."},{"label_en":"Angular Contact Bearings","label_ru":"Радиально-упорные подшипники","body_en":"mounted back-to-back to restrict axial movement during surging.","body_ru":"установлены по схеме «спина к спине», что ограничивает осевое смещение при гидроударах."},{"label_en":"Oil-Filled Motor Housing","label_ru":"Маслонаполненный корпус двигателя","body_en":"lubricates bearings and seals and dissipates heat away from the winding.","body_ru":"смазывает подшипники и уплотнения и отводит тепло от обмотки."},{"label_en":"Double Mechanical Seals","label_ru":"Двойные торцевые уплотнения","body_en":"with moisture detector, operating at submergence pressure.","body_ru":"с датчиком влажности, работают под давлением погружения."},{"label_en":"Moisture Detection","label_ru":"Контроль влажности","body_en":"a built-in moisture detector cuts power to the pump if the mechanical seals fail, preventing winding damage.","body_ru":"встроенный датчик влажности отключает питание насоса при отказе торцевых уплотнений, предотвращая повреждение обмотки."},{"label_en":"Stator Motor","label_ru":"Статор двигателя","body_en":"designed to operate at any supply voltage and vacuum-impregnated.","body_ru":"рассчитан на работу при любом напряжении питания, выполнен с вакуумной пропиткой."},{"label_en":"Cantilever Shaft","label_ru":"Консольный вал","body_en":"separates the motor from the pump end, so the mechanical seal operates at submergence pressure rather than discharge pressure.","body_ru":"отделяет двигатель от насосной части, благодаря чему торцевое уплотнение работает под давлением погружения, а не нагнетания."}]}');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 4, 'text', '{"title_en":"IEC (SANS) standards","title_ru":"Стандарты IEC (SANS)","body_en":"<p>To pump in explosive environments, all Hippo Submersible Pumps comply with IEC (SANS) 60079-0:2005 and IEC (SANS) 60079-1:2004.</p>","body_ru":"<p>Для работы во взрывоопасных средах все погружные насосы Hippo соответствуют стандартам IEC (SANS) 60079-0:2005 и IEC (SANS) 60079-1:2004.</p>"}');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 5, 'text', '{"title_en":"Applications","title_ru":"Применение","body_en":"<p>The Hippo ST range excels in de-watering and drainage applications, and for pumping liquids with entrapped air (froth pumping). Its compact, high-pressure design suits sumps, open pits and pontoons, and units can be installed in series for very high heads such as acid mine-water drainage.</p>","body_ru":"<p>Насосы серии Hippo ST отлично подходят для водоотлива, дренажа и перекачки жидкостей с вовлечённым воздухом (пенные среды). Компактная конструкция, рассчитанная на высокое давление, подходит для приямков, открытых карьеров и понтонов; возможна последовательная установка насосов для получения очень высокого напора, например при откачке кислотных шахтных вод.</p>"}');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 6, 'list', '{"style":"tag","items":[{"en":"General hard dewatering & drainage","ru":"Общий жёсткий водоотлив и дренаж"},{"en":"Slag pits","ru":"Шлаковые приямки"},{"en":"Tailings ponds","ru":"Хвостохранилища"},{"en":"Slurry froth pumping","ru":"Перекачка пенных шламов"},{"en":"Mineral processing","ru":"Переработка полезных ископаемых"},{"en":"Phosphoric acid plants","ru":"Производство фосфорной кислоты"},{"en":"Mine dewatering","ru":"Шахтный водоотлив"}]}');
INSERT INTO pages (slug, title_en, title_ru, eyebrow_en, eyebrow_ru, show_head, show_cta, seo_title_en, crumbs_json) VALUES ('hippo-range/verticals', 'Verticals', 'Вертикальные насосы', 'Hippo Range', 'Линейка Hippo', 1, 1, '', '[{"en":"Home","ru":"Главная","href":"/"},{"en":"Hippo Range","ru":"Линейка Hippo","href":"/hippo-range/"},{"en":"Verticals","ru":"Вертикальные насосы","href":null}]');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 0, 'text', '{"body_en":"<p class=''lede''><strong>Hippo Cantilever Vertical Spindle Heavy Duty Slurry &amp; De-watering Pumps.</strong> The world''s most versatile pump range — an all-metal vertical-spindle design with Bottom Suction, Bottom Discharge, Top Suction and Vortex configurations. Proven reliability and efficiency let the Hippo range handle high-density abrasive and corrosive slurries, running dry at heads up to 110 m and flows up to 1500 l/s.</p>","body_ru":"<p class=''lede''><strong>Консольные вертикальные шпиндельные насосы Hippo для шлама и водоотлива.</strong> Самая универсальная в мире линейка насосов — цельнометаллическая вертикальная шпиндельная конструкция в конфигурациях с нижним всасыванием, нижним нагнетанием, верхним всасыванием и вихревая. Проверенная надёжность и эффективность позволяют линейке Hippo работать с плотными абразивными и коррозионными шламами, выдерживая работу «на сухом ходу» при напоре до 110 м и расходе до 1500 л/с.</p>","max_width":"980px"}');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 1, 'cards', '{"variant":"product","columns":2,"alt":true,"items":[{"image":"/assets/img/vb-design-features.jpg","title_en":"Vertical Bottom Suction Pump (VB)","title_ru":"Вертикальный насос с нижним всасыванием (VB)","body_en":"Used where solids have already settled out and need to be agitated before being pumped.","body_ru":"Применяется там, где твёрдые частицы уже осели и требуют взмучивания перед откачкой.","link_href":"/hippo-range/verticals/vertical-bottom-suction/","link_en":"Configuration","link_ru":"Конфигурация"},{"image":"/assets/img/vb-design-features.jpg","title_en":"Vertical Bottom Discharge (VBD)","title_ru":"Вертикальный насос с нижним нагнетанием (VBD)","body_en":"Used where solids have already settled out and need to be agitated before being pumped, with discharge at the base of the pump.","body_ru":"Применяется там, где твёрдые частицы уже осели и требуют взмучивания перед откачкой; нагнетание выполняется в нижней части насоса.","link_href":"/hippo-range/verticals/vertical-bottom-discharge/","link_en":"Configuration","link_ru":"Конфигурация"},{"image":"/assets/img/vbo-impeller.jpg","title_en":"Vertical Spindle Top Suction Pump (VT)","title_ru":"Вертикальный шпиндельный насос с верхним всасыванием (VT)","body_en":"Used where high discharge pressures exist and for pumping liquids with entrapped air (froth pumping).","body_ru":"Применяется при высоком давлении нагнетания и для перекачки жидкостей с вовлечённым воздухом (пенные среды).","link_href":"/hippo-range/verticals/vertical-top-suction/","link_en":"Configuration","link_ru":"Конфигурация"},{"image":"/assets/img/twin-volute-design-verticals.jpg","title_en":"Vertical Spindle Vortex Pump (VV)","title_ru":"Вертикальный шпиндельный вихревой насос (VV)","body_en":"Used where solids have already settled out and need to be agitated before being pumped, using a vortex hydraulic design.","body_ru":"Применяется там, где твёрдые частицы уже осели и требуют взмучивания перед откачкой, с вихревой гидравлической конструкцией.","link_href":"/hippo-range/verticals/vertical-spindle-vortex-pump/","link_en":"Configuration","link_ru":"Конфигурация"}]}');
INSERT INTO pages (slug, title_en, title_ru, eyebrow_en, eyebrow_ru, show_head, show_cta, seo_title_en, crumbs_json) VALUES ('hippo-range/verticals/vertical-bottom-suction', 'Vertical Bottom Suction Pump', 'Вертикальный насос с нижним всасыванием', 'Hippo Range', 'Линейка Hippo', 1, 1, '', '[{"en":"Home","ru":"Главная","href":"/"},{"en":"Hippo Range","ru":"Линейка Hippo","href":"/hippo-range/"},{"en":"Verticals","ru":"Вертикальные насосы","href":"/hippo-range/verticals/"},{"en":"Vertical Bottom Suction Pump","ru":"Вертикальный насос с нижним всасыванием","href":null}]');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 0, 'backLink', '{"href":"/hippo-range/verticals/","label_en":"Verticals","label_ru":"Вертикальные насосы"}');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 1, 'textImage', '{"image":"/assets/img/vb-design-features.jpg","body_en":"<p class=''lede''>The Hippo Vertical Spindle Bottom Suction Pump Range is used where solid particles have already settled out and need to be agitated before being pumped. The all-metal pump, with a high-chrome hydraulic end as standard, offers durability and high efficiency, and can be manufactured in duplex stainless steel alloys (e.g. CD4MCu) for acidic environments.</p>","body_ru":"<p class=''lede''>Вертикальный шпиндельный насос Hippo с нижним всасыванием применяется там, где твёрдые частицы в жидкости уже осели и требуют взмучивания перед откачкой. Цельнометаллическая конструкция со стандартной гидравлической частью из хромистого чугуна обеспечивает долговечность и высокую эффективность; доступно исполнение из дуплексной нержавеющей стали (например, CD4MCu) для кислотных сред.</p>"}');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 2, 'list', '{"items":[{"en":"Capable of pumping abrasive and corrosive liquids","ru":"Перекачка абразивных и коррозионных жидкостей"},{"en":"Capacities up to 1500 l/s and heads up to 110 m","ru":"Производительность до 1500 л/с, напор до 110 м"},{"en":"Flame/explosion-proof certification to IEC 60079-1","ru":"Взрывозащищённое исполнение по IEC 60079-1"},{"en":"Power installed from 3 kW up to 575 kW","ru":"Мощность от 3 кВт до 575 кВт"},{"en":"Voltage supply up to 6.6 kV at both 50 & 60 Hz","ru":"Напряжение питания до 6,6 кВ при 50 и 60 Гц"},{"en":"Liquids up to 300 °C","ru":"Жидкости с температурой до 300 °C"},{"en":"Can run dry continuously","ru":"Непрерывная работа «на сухом ходу»"},{"en":"Shaft lengths designed to customer requirements","ru":"Длина вала — по требованиям заказчика"},{"en":"Accommodates standard flange-mounted motors","ru":"Совместим со стандартными фланцевыми электродвигателями"},{"en":"Direct-coupled (preferred) or V-belt driven","ru":"Прямая муфта (предпочтительно) или клиноремённый привод"},{"en":"No submerged seals or bearings on the standard pump","ru":"Отсутствие погружных уплотнений и подшипников в стандартном исполнении"}]}');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 3, 'advantages', '{"title_en":"Advantages of the VB configuration","title_ru":"Преимущества конфигурации VB","items":[{"label_en":"Twin Volute Discharge Design","label_ru":"Двухспиральная конструкция нагнетания","body_en":"radial forces are balanced out in the volute, minimising bearing load and increasing bearing life while enabling more efficient pumping.","body_ru":"радиальные силы уравновешиваются в корпусе, что снижает нагрузку на подшипники, увеличивает их ресурс и повышает эффективность перекачки."},{"label_en":"Agitator","label_ru":"Мешалка (агитатор)","body_en":"the Hippo heavy-duty slurry pump range can be fitted with an agitator.","body_ru":"насосы Hippo повышенной прочности могут комплектоваться мешалкой."},{"label_en":"“Run Dry”","label_ru":"«Сухой ход»","body_en":"the stator housing is filled with oil, which dissipates heat away from the winding, enabling continuous dry running under full, partial or non-submerged conditions.","body_ru":"корпус статора заполнен маслом, которое отводит тепло от обмотки, обеспечивая непрерывную работу на сухом ходу при полном, частичном или отсутствующем погружении."},{"label_en":"Cantilever Shaft","label_ru":"Консольный вал","body_en":"the Twin Volute design uses a cantilever shaft, separating the wet end from the motor end without support bearings.","body_ru":"двухспиральная конструкция использует консольный вал, отделяющий проточную часть от двигателя без опорных подшипников."},{"label_en":"Mechanical Seals","label_ru":"Торцевые уплотнения","body_en":"dissociated from the wet end as a result of the cantilever shaft, subject only to submergence pressure — extending seal life.","body_ru":"благодаря консольному валу отделены от проточной части и работают только под давлением погружения, что увеличивает их срок службы."},{"label_en":"Moisture Detection","label_ru":"Контроль влажности","body_en":"a built-in moisture detector cuts power to the pump if the mechanical seals fail, preventing winding damage.","body_ru":"встроенный датчик влажности отключает питание насоса при отказе торцевых уплотнений, предотвращая повреждение обмотки."},{"label_en":"Hydraulic-End Designs","label_ru":"Исполнения гидравлической части","body_en":"a specific hydraulic end is available for every application — high head or high volume, large or irregular solids, abrasive or corrosive liquids.","body_ru":"под каждую задачу доступна своя гидравлическая часть — для высокого напора или большого объёма, крупных или неправильной формы частиц, абразивных или коррозионных сред."}]}');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 4, 'text', '{"title_en":"IEC (SANS) standards","title_ru":"Стандарты IEC (SANS)","body_en":"<p>To pump in explosive environments, all Hippo Submersible Pumps comply with IEC (SANS) 60079-0:2005 and IEC (SANS) 60079-1:2004.</p>","body_ru":"<p>Для работы во взрывоопасных средах все погружные насосы Hippo соответствуют стандартам IEC (SANS) 60079-0:2005 и IEC (SANS) 60079-1:2004.</p>"}');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 5, 'text', '{"title_en":"Applications","title_ru":"Применение","body_en":"<p>The Hippo VB range excels in complex slurry and de-watering applications. Its compact design and high-pressure capability suit pits, pontoons, or temporary and fixed installations.</p>","body_ru":"<p>Насосы серии Hippo VB отлично подходят для сложных задач перекачки шлама и водоотлива. Компактная конструкция и способность работать при высоком давлении позволяют использовать их в карьерах, на понтонах, а также во временных и стационарных установках.</p>"}');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 6, 'list', '{"style":"tag","items":[{"en":"Mineral process plants","ru":"Перерабатывающие предприятия"},{"en":"Mineral excavations","ru":"Горные выработки"},{"en":"Coal mine tunnels","ru":"Угольные тоннели"},{"en":"Slurry pumping","ru":"Перекачка шлама"},{"en":"Flotation cell transfer","ru":"Передача на флотационные камеры"},{"en":"Magnetite recovery","ru":"Извлечение магнетита"},{"en":"Slurry storage sumps","ru":"Приямки хранения шлама"},{"en":"Slurry transport","ru":"Транспортировка шлама"},{"en":"Tailings sumps","ru":"Хвостовые приямки"},{"en":"Thickener feed pumps","ru":"Подача на сгустители"}]}');
