INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 1, 'textImage', '{"image":"/assets/img/vb-design-features.jpg","body_en":"<p class=''lede''>The Hippo Vertical Bottom Discharge Pump Range is used where solid particles have already settled out and need to be agitated before being pumped. The all-metal pump, with a high-chrome hydraulic end as standard, offers durability and high efficiency, and can be manufactured in duplex stainless steel alloys (e.g. CD4MCu) for acidic environments.</p>","body_ru":"<p class=''lede''>Вертикальный насос Hippo с нижним нагнетанием применяется там, где твёрдые частицы в жидкости уже осели и требуют взмучивания перед откачкой. Цельнометаллическая конструкция со стандартной гидравлической частью из хромистого чугуна обеспечивает долговечность и высокую эффективность; доступно исполнение из дуплексной нержавеющей стали (например, CD4MCu) для кислотных сред.</p>"}');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 2, 'list', '{"items":[{"en":"Capable of pumping abrasive and corrosive liquids","ru":"Перекачка абразивных и коррозионных жидкостей"},{"en":"Capacities up to 1500 l/s and heads up to 110 m","ru":"Производительность до 1500 л/с, напор до 110 м"},{"en":"Flame/explosion-proof certification to IEC 60079-1","ru":"Взрывозащищённое исполнение по IEC 60079-1"},{"en":"Power installed from 3 kW up to 575 kW","ru":"Мощность от 3 кВт до 575 кВт"},{"en":"Voltage supply up to 6.6 kV at both 50 & 60 Hz","ru":"Напряжение питания до 6,6 кВ при 50 и 60 Гц"},{"en":"Liquids up to 300 °C","ru":"Жидкости с температурой до 300 °C"},{"en":"Can run dry continuously","ru":"Непрерывная работа «на сухом ходу»"},{"en":"Shaft lengths designed to customer requirements","ru":"Длина вала — по требованиям заказчика"},{"en":"Accommodates standard flange-mounted motors","ru":"Совместим со стандартными фланцевыми электродвигателями"},{"en":"Direct-coupled (preferred) or V-belt driven","ru":"Прямая муфта (предпочтительно) или клиноремённый привод"},{"en":"No submerged seals or bearings on the standard pump","ru":"Отсутствие погружных уплотнений и подшипников в стандартном исполнении"}]}');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 3, 'advantages', '{"title_en":"Advantages of the VBD configuration","title_ru":"Преимущества конфигурации VBD","items":[{"label_en":"Twin Volute Discharge Design","label_ru":"Двухспиральная конструкция нагнетания","body_en":"radial forces are balanced out in the volute, minimising bearing load and increasing bearing life while enabling more efficient pumping.","body_ru":"радиальные силы уравновешиваются в корпусе, что снижает нагрузку на подшипники, увеличивает их ресурс и повышает эффективность перекачки."},{"label_en":"Agitator","label_ru":"Мешалка (агитатор)","body_en":"the Hippo heavy-duty slurry pump range can be fitted with an agitator.","body_ru":"насосы Hippo повышенной прочности могут комплектоваться мешалкой."},{"label_en":"“Run Dry”","label_ru":"«Сухой ход»","body_en":"the stator housing is filled with oil, which dissipates heat away from the winding, enabling continuous dry running under full, partial or non-submerged conditions.","body_ru":"корпус статора заполнен маслом, которое отводит тепло от обмотки, обеспечивая непрерывную работу на сухом ходу при полном, частичном или отсутствующем погружении."},{"label_en":"Cantilever Shaft","label_ru":"Консольный вал","body_en":"the Twin Volute design uses a cantilever shaft, separating the wet end from the motor end without support bearings.","body_ru":"двухспиральная конструкция использует консольный вал, отделяющий проточную часть от двигателя без опорных подшипников."},{"label_en":"Mechanical Seals","label_ru":"Торцевые уплотнения","body_en":"dissociated from the wet end as a result of the cantilever shaft, subject only to submergence pressure — extending seal life.","body_ru":"благодаря консольному валу отделены от проточной части и работают только под давлением погружения, что увеличивает их срок службы."},{"label_en":"Moisture Detection","label_ru":"Контроль влажности","body_en":"a built-in moisture detector cuts power to the pump if the mechanical seals fail, preventing winding damage.","body_ru":"встроенный датчик влажности отключает питание насоса при отказе торцевых уплотнений, предотвращая повреждение обмотки."},{"label_en":"Hydraulic-End Designs","label_ru":"Исполнения гидравлической части","body_en":"a specific hydraulic end is available for every application — high head or high volume, large or irregular solids, abrasive or corrosive liquids.","body_ru":"под каждую задачу доступна своя гидравлическая часть — для высокого напора или большого объёма, крупных или неправильной формы частиц, абразивных или коррозионных сред."}]}');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 4, 'text', '{"title_en":"IEC (SANS) standards","title_ru":"Стандарты IEC (SANS)","body_en":"<p>To pump in explosive environments, all Hippo Submersible Pumps comply with IEC (SANS) 60079-0:2005 and IEC (SANS) 60079-1:2004.</p>","body_ru":"<p>Для работы во взрывоопасных средах все погружные насосы Hippo соответствуют стандартам IEC (SANS) 60079-0:2005 и IEC (SANS) 60079-1:2004.</p>"}');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 5, 'text', '{"title_en":"Applications","title_ru":"Применение","body_en":"<p>The Hippo VBD range is used in complex slurry and de-watering applications. Its compact design and high-pressure capability suit pits, pontoons, or temporary and fixed installations.</p>","body_ru":"<p>Насосы серии Hippo VBD применяются в сложных задачах перекачки шлама и водоотлива. Компактная конструкция и способность работать при высоком давлении позволяют использовать их в карьерах, на понтонах, а также во временных и стационарных установках.</p>"}');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 6, 'list', '{"style":"tag","items":[{"en":"Mineral process plants","ru":"Перерабатывающие предприятия"},{"en":"Mineral excavations","ru":"Горные выработки"},{"en":"Coal mine tunnels","ru":"Угольные тоннели"},{"en":"Slurry pumping","ru":"Перекачка шлама"},{"en":"Flotation cell transfer","ru":"Передача на флотационные камеры"},{"en":"Magnetite recovery","ru":"Извлечение магнетита"},{"en":"Slurry storage sumps","ru":"Приямки хранения шлама"},{"en":"Slurry transport","ru":"Транспортировка шлама"},{"en":"Tailings sumps","ru":"Хвостовые приямки"},{"en":"Thickener feed pumps","ru":"Подача на сгустители"}]}');
INSERT INTO pages (slug, title_en, title_ru, eyebrow_en, eyebrow_ru, show_head, show_cta, seo_title_en, crumbs_json) VALUES ('hippo-range/verticals/vertical-top-suction', 'Vertical Spindle Top Suction Pump', 'Вертикальный шпиндельный насос с верхним всасыванием', 'Hippo Range', 'Линейка Hippo', 1, 1, '', '[{"en":"Home","ru":"Главная","href":"/"},{"en":"Hippo Range","ru":"Линейка Hippo","href":"/hippo-range/"},{"en":"Verticals","ru":"Вертикальные насосы","href":"/hippo-range/verticals/"},{"en":"Vertical Spindle Top Suction Pump","ru":"Вертикальный шпиндельный насос с верхним всасыванием","href":null}]');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 0, 'backLink', '{"href":"/hippo-range/verticals/","label_en":"Verticals","label_ru":"Вертикальные насосы"}');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 1, 'textImage', '{"image":"/assets/img/vbo-impeller.jpg","body_en":"<p class=''lede''>The Hippo Vertical Spindle Top Suction Slurry Pump Range is used where high discharge pressures exist and for pumping liquids with entrapped air (froth pumping). The all-metal pump, with high-chrome hydraulics as standard, offers durability and high efficiency, and can be manufactured in duplex stainless steel alloys (e.g. CD4MCu) for acidic environments.</p>","body_ru":"<p class=''lede''>Вертикальный шпиндельный насос Hippo с верхним всасыванием применяется при высоком давлении нагнетания и для перекачки жидкостей с вовлечённым воздухом (пенные среды). Цельнометаллическая конструкция со стандартной гидравликой из хромистого чугуна обеспечивает долговечность и высокую эффективность; доступно исполнение из дуплексной нержавеющей стали (например, CD4MCu) для кислотных сред.</p>"}');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 2, 'list', '{"items":[{"en":"Capable of pumping abrasive and corrosive liquids","ru":"Перекачка абразивных и коррозионных жидкостей"},{"en":"Capacities up to 1500 l/s and heads up to 110 m","ru":"Производительность до 1500 л/с, напор до 110 м"},{"en":"Flame/explosion-proof certification to IEC 60079-1","ru":"Взрывозащищённое исполнение по IEC 60079-1"},{"en":"Power installed from 3 kW up to 575 kW","ru":"Мощность от 3 кВт до 575 кВт"},{"en":"Voltage supply up to 6.6 kV at both 50 & 60 Hz","ru":"Напряжение питания до 6,6 кВ при 50 и 60 Гц"},{"en":"Liquids up to 300 °C","ru":"Жидкости с температурой до 300 °C"},{"en":"Can run dry continuously","ru":"Непрерывная работа «на сухом ходу»"},{"en":"Shaft lengths designed to customer requirements","ru":"Длина вала — по требованиям заказчика"},{"en":"Accommodates standard flange-mounted motors","ru":"Совместим со стандартными фланцевыми электродвигателями"},{"en":"Direct-coupled (preferred) or V-belt driven","ru":"Прямая муфта (предпочтительно) или клиноремённый привод"},{"en":"No submerged seals or bearings on the standard pump","ru":"Отсутствие погружных уплотнений и подшипников в стандартном исполнении"}]}');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 3, 'advantages', '{"title_en":"Advantages of the VT configuration","title_ru":"Преимущества конфигурации VT","items":[{"label_en":"Twin Volute Discharge Design","label_ru":"Двухспиральная конструкция нагнетания","body_en":"radial forces are balanced out in the volute, minimising bearing load and increasing bearing life while enabling more efficient pumping.","body_ru":"радиальные силы уравновешиваются в корпусе, что снижает нагрузку на подшипники, увеличивает их ресурс и повышает эффективность перекачки."},{"label_en":"Agitator","label_ru":"Мешалка (агитатор)","body_en":"the Hippo heavy-duty slurry pump range can be fitted with an agitator.","body_ru":"насосы Hippo повышенной прочности могут комплектоваться мешалкой."},{"label_en":"“Run Dry”","label_ru":"«Сухой ход»","body_en":"the stator housing is filled with oil, which dissipates heat away from the winding, enabling continuous dry running under full, partial or non-submerged conditions.","body_ru":"корпус статора заполнен маслом, которое отводит тепло от обмотки, обеспечивая непрерывную работу на сухом ходу при полном, частичном или отсутствующем погружении."},{"label_en":"Cantilever Shaft","label_ru":"Консольный вал","body_en":"the Twin Volute design uses a cantilever shaft, separating the wet end from the motor end without support bearings.","body_ru":"двухспиральная конструкция использует консольный вал, отделяющий проточную часть от двигателя без опорных подшипников."},{"label_en":"Mechanical Seals","label_ru":"Торцевые уплотнения","body_en":"dissociated from the wet end as a result of the cantilever shaft, subject only to submergence pressure — extending seal life.","body_ru":"благодаря консольному валу отделены от проточной части и работают только под давлением погружения, что увеличивает их срок службы."},{"label_en":"Moisture Detection","label_ru":"Контроль влажности","body_en":"a built-in moisture detector cuts power to the pump if the mechanical seals fail, preventing winding damage.","body_ru":"встроенный датчик влажности отключает питание насоса при отказе торцевых уплотнений, предотвращая повреждение обмотки."},{"label_en":"Hydraulic-End Designs","label_ru":"Исполнения гидравлической части","body_en":"a specific hydraulic end is available for every application — high head or high volume, large or irregular solids, abrasive or corrosive liquids.","body_ru":"под каждую задачу доступна своя гидравлическая часть — для высокого напора или большого объёма, крупных или неправильной формы частиц, абразивных или коррозионных сред."}]}');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 4, 'text', '{"title_en":"IEC (SANS) standards","title_ru":"Стандарты IEC (SANS)","body_en":"<p>To pump in explosive environments, all Hippo Submersible Pumps comply with IEC (SANS) 60079-0:2005 and IEC (SANS) 60079-1:2004.</p><p>Type VBO — Open Vane Type Impeller with Agitator.</p>","body_ru":"<p>Для работы во взрывоопасных средах все погружные насосы Hippo соответствуют стандартам IEC (SANS) 60079-0:2005 и IEC (SANS) 60079-1:2004.</p><p>Тип VBO — открытое рабочее колесо с мешалкой.</p>"}');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 5, 'text', '{"title_en":"Applications","title_ru":"Применение","body_en":"<p>The Hippo VT range excels in de-watering and drainage applications, and for pumping liquids with entrapped air (froth pumping). Units can be installed in series to accommodate very high heads, such as acid mine-water drainage.</p>","body_ru":"<p>Насосы серии Hippo VT отлично подходят для водоотлива, дренажа и перекачки жидкостей с вовлечённым воздухом (пенные среды). Возможна последовательная установка насосов для получения очень высокого напора, например при откачке кислотных шахтных вод.</p>"}');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 6, 'list', '{"style":"tag","items":[{"en":"General hard dewatering & drainage","ru":"Общий жёсткий водоотлив и дренаж"},{"en":"Slag pits","ru":"Шлаковые приямки"},{"en":"Tailings ponds","ru":"Хвостохранилища"},{"en":"Slurry froth pumping","ru":"Перекачка пенных шламов"},{"en":"Mineral processing","ru":"Переработка полезных ископаемых"},{"en":"Phosphoric acid plants","ru":"Производство фосфорной кислоты"},{"en":"Mine dewatering","ru":"Шахтный водоотлив"}]}');
