INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 1, 'textImage', '{"image":"/assets/img/twin-volute-design-verticals.jpg","body_en":"<p class=''lede''>The Hippo Vertical Spindle Vortex Pump Range is used where solid particles have already settled out and need to be agitated before being pumped. The all-metal pump, with a high-chrome hydraulic end as standard, offers durability and high efficiency, and can be manufactured in duplex stainless steel alloys (e.g. CD4MCu) for acidic environments.</p>","body_ru":"<p class=''lede''>Вертикальный шпиндельный вихревой насос Hippo применяется там, где твёрдые частицы в жидкости уже осели и требуют взмучивания перед откачкой. Цельнометаллическая конструкция со стандартной гидравлической частью из хромистого чугуна обеспечивает долговечность и высокую эффективность; доступно исполнение из дуплексной нержавеющей стали (например, CD4MCu) для кислотных сред.</p>"}');
