INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 0, 'textImage', '{"image":"/assets/img/cd4mcu-steel.jpg","title_en":"The offering","title_ru":"Наше предложение","body_en":"<p class=''lede''>Hazleton Pumps, based in Centurion, South Africa, designs and manufactures the Hippo range of custom-engineered, heavy-duty slurry pumping solutions — cast and assembled in South Africa to the customer''s requirements at duty point.</p>","body_ru":"<p class=''lede''>Компания Hazleton Pumps из города Сентурион (ЮАР) проектирует и производит линейку шламовых насосных решений Hippo повышенной прочности, изготавливаемых по индивидуальному проекту — отливка и сборка выполняются в Южной Африке под требования заказчика в рабочей точке.</p>","image_side":"right"}');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 1, 'list', '{"items":[{"en":"Motors from 5.5 kW to 850 kW","ru":"Электродвигатели от 5,5 кВт до 850 кВт"},{"en":"Engineered to displace corrosive and abrasive slurry in heavy-duty mining and industrial applications","ru":"Рассчитаны на перекачку коррозионных и абразивных шламов в тяжёлых горнодобывающих и промышленных задачах"},{"en":"Capacities up to 1500 litres per second","ru":"Производительность до 1500 литров в секунду"},{"en":"Liquids up to 95 °C","ru":"Жидкости с температурой до 95 °C"},{"en":"Heads up to 250 m","ru":"Напор до 250 м"},{"en":"24-month guarantee","ru":"Гарантия 24 месяца"}]}');
