INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 0, 'text', '{"body_en":"<p class=''lede''>Performance curves for the Hippo pump range, across pole speeds, frequencies and voltage classes. Contact us for curves matching your specific duty point.</p>","body_ru":"<p class=''lede''>Напорные характеристики насосов линейки Hippo для различных частот вращения, частот сети и классов напряжения. Свяжитесь с нами, чтобы подобрать кривую под вашу рабочую точку.</p>"}');
INSERT INTO blocks (page_id, sort_order, type, data) VALUES (@page_id, 1, 'curveGroups', '{"groups":[{"title_en":"50 Hz Curves — Low Voltage","title_ru":"Характеристики 50 Гц — низкое напряжение","items":[{"title_en":"Hippo 2-Pole 50 Hz Curve — Low Voltage","title_ru":"Hippo, 2 полюса, 50 Гц — низкое напряжение","image":"/assets/img/Hippo-2-Pole-Speed-50-Hz-Curve-Low-Voltage.jpg"},{"title_en":"Hippo 4-Pole 50 Hz Curve — Low Voltage","title_ru":"Hippo, 4 полюса, 50 Гц — низкое напряжение","image":"/assets/img/Hippo-4-Pole-Speed-50-Hz-Curve-Low-Voltage.jpg"},{"title_en":"Hippo 6-Pole 50 Hz Curve — Low Voltage","title_ru":"Hippo, 6 полюсов, 50 Гц — низкое напряжение","image":"/assets/img/Hippo-6-Pole-Speed-50-Hz-Curve-Low-Voltage.jpg"}]},{"title_en":"50 Hz Curves — Medium/High Voltage","title_ru":"Характеристики 50 Гц — среднее/высокое напряжение","items":[{"title_en":"Hippo 2-Pole 50 Hz Curve — Medium/High Voltage","title_ru":"Hippo, 2 полюса, 50 Гц — среднее/высокое напряжение","image":"/assets/img/Hippo-2-Pole-Speed-50-Hz-Curve-MediumHigh-Voltage.jpg"},{"title_en":"Hippo 4-Pole 50 Hz Curve — Medium/High Voltage","title_ru":"Hippo, 4 полюса, 50 Гц — среднее/высокое напряжение","image":"/assets/img/Hippo-4-Pole-Speed-50-Hz-Curve-MediumHigh-Voltage.jpg"},{"title_en":"Hippo 6-Pole 50 Hz Curve — Medium/High Voltage","title_ru":"Hippo, 6 полюсов, 50 Гц — среднее/высокое напряжение","image":"/assets/img/Hippo-6-Pole-Speed-50-Hz-Curve-MediumHigh-Voltage.jpg"}]},{"title_en":"60 Hz Curves — Low Voltage","title_ru":"Характеристики 60 Гц — низкое напряжение","items":[{"title_en":"Hippo 2-Pole 60 Hz Curve — Low Voltage","title_ru":"Hippo, 2 полюса, 60 Гц — низкое напряжение","image":"/assets/img/Hippo-2-Pole-Speed-60-Hz-Curve-Low-Votage.jpg"},{"title_en":"Hippo 4-Pole 60 Hz Curve — Low Voltage","title_ru":"Hippo, 4 полюса, 60 Гц — низкое напряжение","image":"/assets/img/Hippo-4-Pole-Speed-60-Hz-Curve-Low-Votage.jpg"},{"title_en":"Hippo 6-Pole 60 Hz Curve — Low Voltage","title_ru":"Hippo, 6 полюсов, 60 Гц — низкое напряжение","image":"/assets/img/Hippo-6-Pole-Speed-60-Hz-Curve-Low-Votage.jpg"}]},{"title_en":"60 Hz Curves — Medium/High Voltage","title_ru":"Характеристики 60 Гц — среднее/высокое напряжение","items":[{"title_en":"Hippo 2-Pole 60 Hz Curve — Medium/High Voltage","title_ru":"Hippo, 2 полюса, 60 Гц — среднее/высокое напряжение","image":"/assets/img/Hippo-2-Pole-Speed-60-Hz-Curve-MediumHigh-Voltage.jpg"},{"title_en":"Hippo 4-Pole 60 Hz Curve — Medium/High Voltage","title_ru":"Hippo, 4 полюса, 60 Гц — среднее/высокое напряжение","image":"/assets/img/Hippo-4-Pole-Speed-60-Hz-Curve-MediumHigh-Voltage.jpg"},{"title_en":"Hippo 6-Pole 60 Hz Curve — Medium/High Voltage","title_ru":"Hippo, 6 полюсов, 60 Гц — среднее/высокое напряжение","image":"/assets/img/Hippo-6-Pole-Speed-60-Hz-Curve-MediumHigh-Voltage.jpg"}]}]}');
