INSERT INTO case_studies (slug, title_en, title_ru, image, challenge_en, challenge_ru, sort_order) VALUES ('foskor-richards-bay-south-africa', 'Foskor, Richards Bay — South Africa', 'Фоскор, Ричардс-Бей — ЮАР', '/assets/img/case-new-denmark.jpg', 'Foskor, a plant producing sulphuric acid (H₂SO₄), phosphoric acid (H₃PO₄) and granular fertiliser (MAP/DAP), needed a durable solution for pumping highly corrosive slurries.', 'Завод Foskor, производящий серную кислоту (H₂SO₄), фосфорную кислоту (H₃PO₄) и гранулированные удобрения (MAP/DAP), нуждался в надёжном решении для перекачки высококоррозионных шламов.', 0);
INSERT INTO case_study_solutions (case_study_id, text_en, text_ru, sort_order) VALUES (@cs_id, 'Hazleton Pumps International designed and manufactured fit-for-purpose vertical spindle slurry pumps for the project.', 'Hazleton Pumps International спроектировала и изготовила вертикальные шпиндельные шламовые насосы, подобранные под задачу проекта.', 0);
INSERT INTO case_study_solutions (case_study_id, text_en, text_ru, sort_order) VALUES (@cs_id, 'Pumps manufactured from CD4MCu duplex stainless steel for resistance to pH below 4.', 'Насосы изготовлены из дуплексной нержавеющей стали CD4MCu для устойчивости к средам с pH ниже 4.', 1);
INSERT INTO case_studies (slug, title_en, title_ru, image, challenge_en, challenge_ru, sort_order) VALUES ('apatite-phosphate-mine-russia', 'Apatite Phosphate Mine — Russia', 'Апатитовое месторождение — Россия', '/assets/img/case-apatite-russia.webp', '', '', 1);
INSERT INTO case_study_solutions (case_study_id, text_en, text_ru, sort_order) VALUES (@cs_id, 'The project called for vertical spindle pumps.', 'Проект требовал применения вертикальных шпиндельных насосов.', 0);
INSERT INTO case_study_solutions (case_study_id, text_en, text_ru, sort_order) VALUES (@cs_id, 'Motors selected according to voltage and optimal pole speeds.', 'Электродвигатели подобраны по напряжению и оптимальной частоте вращения.', 1);
INSERT INTO case_study_solutions (case_study_id, text_en, text_ru, sort_order) VALUES (@cs_id, 'Materials adapted to suit the application.', 'Материалы адаптированы под условия применения.', 2);
INSERT INTO case_study_solutions (case_study_id, text_en, text_ru, sort_order) VALUES (@cs_id, 'Best efficiency through custom design.', 'Максимальная эффективность за счёт индивидуального проектирования.', 3);
INSERT INTO case_study_solutions (case_study_id, text_en, text_ru, sort_order) VALUES (@cs_id, 'Reasonable cost of ownership.', 'Экономически обоснованная стоимость владения.', 4);
INSERT INTO case_study_solutions (case_study_id, text_en, text_ru, sort_order) VALUES (@cs_id, 'Minimum downtime: reliability and durability.', 'Минимальные простои: надёжность и долговечность.', 5);
INSERT INTO case_study_solutions (case_study_id, text_en, text_ru, sort_order) VALUES (@cs_id, 'Can run dry.', 'Возможность работы «на сухом ходу».', 6);
INSERT INTO case_study_solutions (case_study_id, text_en, text_ru, sort_order) VALUES (@cs_id, 'Double discharge volute provides balanced radial loads on bearings and seals.', 'Двухспиральный корпус обеспечивает сбалансированные радиальные нагрузки на подшипники и уплотнения.', 7);
INSERT INTO case_studies (slug, title_en, title_ru, image, challenge_en, challenge_ru, sort_order) VALUES ('rossing-uranium-namibia', 'Rössing Uranium — Namibia', 'Урановый рудник Рёссинг — Намибия', '/assets/img/case-rossing-namibia.webp', 'The project required heavy-duty vertical spindle slurry pumps for pontoon installation, capable of handling corrosive slurry with a pH below 4, and ambient temperatures of up to 43 °C in Namibia''s desert climate.', 'Проект требовал тяжёлых вертикальных шпиндельных шламовых насосов для установки на понтонах, способных работать с коррозионным шламом с pH ниже 4 при температуре окружающей среды до 43 °C в условиях пустынного климата Намибии.', 2);
INSERT INTO case_study_solutions (case_study_id, text_en, text_ru, sort_order) VALUES (@cs_id, 'Pumps cast and manufactured from CD4MCu duplex stainless steel to withstand corrosion.', 'Насосы отлиты и изготовлены из дуплексной нержавеющей стали CD4MCu для устойчивости к коррозии.', 0);
INSERT INTO case_study_solutions (case_study_id, text_en, text_ru, sort_order) VALUES (@cs_id, '185 kW and 250 kW motors sized for the slurry''s specific gravity.', 'Электродвигатели 185 кВт и 250 кВт подобраны под удельный вес шлама.', 1);
INSERT INTO case_study_solutions (case_study_id, text_en, text_ru, sort_order) VALUES (@cs_id, 'Reasonable cost of ownership and long-term value.', 'Экономически обоснованная стоимость владения и долгосрочная ценность.', 2);
INSERT INTO case_study_solutions (case_study_id, text_en, text_ru, sort_order) VALUES (@cs_id, 'Minimum downtime: reliability and durability.', 'Минимальные простои: надёжность и долговечность.', 3);
INSERT INTO case_study_solutions (case_study_id, text_en, text_ru, sort_order) VALUES (@cs_id, 'Design allows the pumps to run dry.', 'Конструкция позволяет насосам работать «на сухом ходу».', 4);
INSERT INTO case_study_solutions (case_study_id, text_en, text_ru, sort_order) VALUES (@cs_id, 'Double discharge volute design provides balanced radial loads, increasing bearing life.', 'Двухспиральная конструкция обеспечивает сбалансированные радиальные нагрузки, увеличивая ресурс подшипников.', 5);
INSERT INTO case_studies (slug, title_en, title_ru, image, challenge_en, challenge_ru, sort_order) VALUES ('new-denmark-colliery-south-africa', 'New Denmark Colliery — South Africa', 'Угольная шахта Нью-Денмарк — ЮАР', '/assets/img/case-new-denmark.jpg', '', '', 3);
INSERT INTO case_study_solutions (case_study_id, text_en, text_ru, sort_order) VALUES (@cs_id, 'Certified flameproof submersible slurry pumps with flameproof electrical control panels for added protection.', 'Сертифицированные взрывозащищённые погружные шламовые насосы с взрывозащищёнными электрощитами управления для дополнительной защиты.', 0);
INSERT INTO case_study_solutions (case_study_id, text_en, text_ru, sort_order) VALUES (@cs_id, 'Designed for underground coal mines with flammable dust and combustible methane present.', 'Разработаны для подземных угольных шахт с наличием горючей пыли и метана.', 1);
INSERT INTO case_study_solutions (case_study_id, text_en, text_ru, sort_order) VALUES (@cs_id, 'Manufactured from cast iron and hard chrome.', 'Изготовлены из чугуна и хромистого чугуна.', 2);
INSERT INTO case_study_solutions (case_study_id, text_en, text_ru, sort_order) VALUES (@cs_id, 'Complies with IEC 60079 flameproof specifications.', 'Соответствуют взрывозащищённым требованиям IEC 60079.', 3);
INSERT INTO case_study_solutions (case_study_id, text_en, text_ru, sort_order) VALUES (@cs_id, 'Can be designed for any electrical supply voltage, including high voltage, at 50 or 60 Hz.', 'Могут изготавливаться под любое напряжение питания, включая высокое, при 50 или 60 Гц.', 4);
INSERT INTO case_study_solutions (case_study_id, text_en, text_ru, sort_order) VALUES (@cs_id, 'Trolley or skid available for ease of movement underground.', 'Доступна тележка или салазки для удобства перемещения под землёй.', 5);
INSERT INTO case_study_solutions (case_study_id, text_en, text_ru, sort_order) VALUES (@cs_id, 'Safety controls protect the pumps from overload, heat or excessive vibration.', 'Системы защиты оберегают насосы от перегрузки, перегрева и избыточной вибрации.', 6);
INSERT INTO case_studies (slug, title_en, title_ru, image, challenge_en, challenge_ru, sort_order) VALUES ('new-vaal-colliery-south-africa', 'New Vaal Colliery — South Africa', 'Угольная шахта Нью-Ваал — ЮАР', '/assets/img/case-new-vaal.jpg', 'Hazleton Pumps International was approached for a slurry pumping solution at the New Vaal Colliery project in South Africa, where a permanent installation was required for coal slurry.', 'К Hazleton Pumps International обратились за решением для перекачки шлама на проекте угольной шахты Нью-Ваал в ЮАР, где требовалась стационарная установка для угольного шлама.', 4);
INSERT INTO case_study_solutions (case_study_id, text_en, text_ru, sort_order) VALUES (@cs_id, 'Heavy-duty vertical spindle slurry pumps were supplied complete with motors.', 'Поставлены тяжёлые вертикальные шпиндельные шламовые насосы в комплекте с электродвигателями.', 0);
INSERT INTO case_study_solutions (case_study_id, text_en, text_ru, sort_order) VALUES (@cs_id, 'A total of 68 Hippo vertical spindle slurry pumps (75L and 100L models) were designed and manufactured for New Vaal Colliery.', 'Всего для шахты Нью-Ваал спроектировано и изготовлено 68 вертикальных шпиндельных насосов Hippo (модели 75L и 100L).', 1);
INSERT INTO case_studies (slug, title_en, title_ru, image, challenge_en, challenge_ru, sort_order) VALUES ('amandelbult-platinum-mine-south-africa', 'Amandelbult Platinum Mine — South Africa', 'Платиновый рудник Амандельбюлт — ЮАР', '/assets/img/case-amandelbult.jpg', 'Amandelbult mine, in the Thabazimbi area of South Africa''s North-West Province, produces platinum-group metals valued for jewellery (for platinum''s purity and resistance to tarnishing) and for catalytic converters.', 'Рудник Амандельбюлт расположен в районе Табазимби северо-западной провинции ЮАР и добывает металлы платиновой группы, востребованные в ювелирном деле (благодаря чистоте и устойчивости платины к потускнению) и в производстве каталитических нейтрализаторов.', 5);
INSERT INTO case_study_solutions (case_study_id, text_en, text_ru, sort_order) VALUES (@cs_id, 'Pumps designed to handle heavy-duty, highly abrasive slurries.', 'Насосы рассчитаны на перекачку тяжёлых высокоабразивных шламов.', 0);
INSERT INTO case_study_solutions (case_study_id, text_en, text_ru, sort_order) VALUES (@cs_id, 'Fixed installation on frames within a sump at the plant.', 'Стационарная установка на рамах в приямке предприятия.', 1);
INSERT INTO case_studies (slug, title_en, title_ru, image, challenge_en, challenge_ru, sort_order) VALUES ('tautona-gold-mine-south-africa', 'TauTona Gold Mine — South Africa', 'Золотой рудник ТауТона — ЮАР', '/assets/img/case-tautona.jpg', 'This mining operation near Carletonville, South Africa, is the deepest in the world — reaching 3,900 m.', 'Этот рудник близ Карлтонвилля в ЮАР — самый глубокий в мире: глубина разработки достигает 3900 м.', 6);
INSERT INTO case_study_solutions (case_study_id, text_en, text_ru, sort_order) VALUES (@cs_id, 'Heavy-duty submersible slurry pumps manufactured with a 28% hard-chrome wet end for durability.', 'Погружные шламовые насосы повышенной прочности с проточной частью из хромистого чугуна (28% хрома) для долговечности.', 0);
INSERT INTO case_study_solutions (case_study_id, text_en, text_ru, sort_order) VALUES (@cs_id, 'Designed for underground gold-mine conditions with abrasive material.', 'Разработаны для условий подземного золотодобывающего рудника с абразивными материалами.', 1);
INSERT INTO case_study_solutions (case_study_id, text_en, text_ru, sort_order) VALUES (@cs_id, 'Pumps can be designed for any electrical supply voltage, including high voltage, at 50 or 60 Hz.', 'Насосы могут изготавливаться под любое напряжение питания, включая высокое, при 50 или 60 Гц.', 2);
INSERT INTO case_studies (slug, title_en, title_ru, image, challenge_en, challenge_ru, sort_order) VALUES ('cullinan-diamond-mine-south-africa', 'Cullinan Diamond Mine — South Africa', 'Алмазный рудник Куллинан — ЮАР', '/assets/img/case-cullinan.jpg', '', '', 7);
INSERT INTO case_study_solutions (case_study_id, text_en, text_ru, sort_order) VALUES (@cs_id, 'Hazleton Pumps International designed and manufactured three 350VBDC, 600 kW Hippo Bottom Suction vertical spindle pumps for Petra Diamonds'' Cullinan Diamond Mine.', 'Hazleton Pumps International спроектировала и изготовила три вертикальных шпиндельных насоса Hippo с нижним всасыванием модели 350VBDC мощностью 600 кВт для алмазного рудника Куллинан компании Petra Diamonds.', 0);
INSERT INTO case_study_solutions (case_study_id, text_en, text_ru, sort_order) VALUES (@cs_id, 'The fixed installation pumps water from the dam to the process plant, where dust and dirt are washed from the diamond-bearing gravel.', 'Стационарная установка подаёт воду из дамбы на перерабатывающий завод, где от алмазосодержащего гравия отмываются пыль и грязь.', 1);
INSERT INTO case_studies (slug, title_en, title_ru, image, challenge_en, challenge_ru, sort_order) VALUES ('kenmare-titanium-sands-mozambique', 'Kenmare Titanium Sands — Mozambique', 'Титановые пески Кенмаре — Мозамбик', '/assets/img/case-kenmare.jpg', 'The Kenmare project in Mozambique needed a solution for pumping sand slurry containing titanium; extreme abrasion levels in the slurry challenged equipment durability.', 'Проект Kenmare в Мозамбике требовал решения для перекачки песчаного шлама с содержанием титана; экстремальная абразивность шлама предъявляла высокие требования к долговечности оборудования.', 8);
INSERT INTO case_study_solutions (case_study_id, text_en, text_ru, sort_order) VALUES (@cs_id, 'Heavy-duty submersible slurry pumps were needed for pontoon installation, with chain blocks and electrical control panels.', 'Для установки на понтонах потребовались погружные шламовые насосы повышенной прочности с цепными талями и электрощитами управления.', 0);
INSERT INTO case_study_solutions (case_study_id, text_en, text_ru, sort_order) VALUES (@cs_id, 'A total of 18 Hippo submersible slurry pumps (75M and 200DM models) were designed and manufactured for Kenmare.', 'Для компании Kenmare спроектировано и изготовлено 18 погружных шламовых насосов Hippo (модели 75M и 200DM).', 1);
INSERT INTO articles (slug, title_en, title_ru, date_en, date_ru, image, teaser_en, teaser_ru, body_en, body_ru, sort_order) VALUES ('sa-hippo-to-exhibit-at-pdac-in-toronto', 'SA Hippo to exhibit at PDAC in Toronto', 'Южноафриканский Hippo на выставке PDAC в Торонто', '2 February 2017', '2 февраля 2017 г.', '/assets/img/press-sa-pump-toronto.jpg', 'The PDAC International Convention, Trade Show & Investors Exchange is the world''s leading convention for people, companies and organisations connected with mineral exploration, drawing over 900 exhibitors and 22,000 attendees from 100+ countries…', 'Международная конференция, выставка и инвестиционная биржа PDAC — ведущее в мире мероприятие для компаний и специалистов в области геологоразведки, собирающее более 900 экспонентов и 22 000 участников из более чем 100 стран…', '<p>The PDAC International Convention, Trade Show &amp; Investors Exchange is the world''s leading convention for people, companies and organisations in, or connected with, mineral exploration. Over 900 exhibitors and 22,000 attendees from more than 100 countries attend, alongside technical sessions, short courses and networking events. Held annually in Toronto, Canada since 1932, it is today the event of choice for the world''s mineral industry.</p>
INSERT INTO articles (slug, title_en, title_ru, date_en, date_ru, image, teaser_en, teaser_ru, body_en, body_ru, sort_order) VALUES ('reducing-the-hidden-cost-of-electrical-submersible-pumps', 'Reducing the hidden cost of electrical submersible pumps', 'Как снизить скрытые расходы на эксплуатацию погружных насосов', '25 February 2015', '25 февраля 2015 г.', '/assets/img/cd4mcu-steel.jpg', 'Electrical submersible pumps are, once installed, usually out of sight and out of mind — with little attention paid to their real operating costs. We look at total cost of ownership rather than purchase price alone…', 'После установки погружные электронасосы обычно скрыты из виду, и их реальная стоимость эксплуатации редко оказывается в центре внимания. В статье рассматривается совокупная стоимость владения, а не только цена покупки…', '<p>Electrical submersible pumps, once installed, are usually fully submerged and out of sight — so their real running costs tend to get little attention. When buying a submersible pump, or any capital equipment, the key measure is total cost of ownership: power usage, maintenance, and the cost of downtime, not just the purchase price. Many factors affect a submersible pump''s service life, and getting them wrong leads to costs that could easily have been avoided.</p>
